local SettingRefBase = require('Game.Setting.SettingRefBase')
---@class EquipLabelVo
local EquipLabelVo = Class("EquipLabelVo", SettingRefBase)

local base = SettingRefBase
local ParseUtils = CS.ParseUtils

function EquipLabelVo:__init()
    self.name = nil
end

function EquipLabelVo:__delete()
    self.name = nil
end

---FillVo
---@param row TableML.TableFileRow
function EquipLabelVo:FillVo(row)
    base.FillVo(self, row)

    self.name = ParseUtils.ParseLocalizeText(row, "name")

    self.labelTypeIcon = ParseUtils.ParsePathName(row, "icon")

    local t = string.split2(self.labelTypeIcon, '.')
    table.insert(t, 2, 'tips.')
    self.nameBg = table.concat(t)
end

return EquipLabelVo